// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice expose a deposit function for that can
/// deposit a specific share of token0 and token1.
/// @dev this deposit feature will be used by public actor.
interface IArrakisLPModulePublic {
    // #region events.

    /// @notice Event describing a deposit done by an user inside this module.
    /// @dev deposit action can be indexed by depositor.
    /// @param depositor address of the tokens provider.
    /// @param proportion percentage of the current position that depositor want to increase.
    /// @param amount0 amount of token0 needed to increase the portfolio of "proportion" percent.
    /// @param amount1 amount of token1 needed to increase the portfolio of "proportion" percent.
    event LogDeposit(
        address depositor,
        uint256 proportion,
        uint256 amount0,
        uint256 amount1
    );

    // #endregion events.

    /// @notice deposit function for public vault.
    /// @param depositor_ address that will provide the tokens.
    /// @param proportion_ percentage of portfolio position vault want to expand.
    /// @return amount0 amount of token0 needed to expand the portfolio by "proportion"
    /// percent.
    /// @return amount1 amount of token1 needed to expand the portfolio by "proportion"
    /// percent.
    function deposit(
        address depositor_,
        uint256 proportion_
    ) external payable returns (uint256 amount0, uint256 amount1);
}

src/interfaces/IArrakisMetaVaultPublic.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IArrakisMetaVaultPublic {
    // #region errors.

    error MintZero();
    error BurnZero();

    // #endregion errors.

    // #region events.

    /// @notice event emitted when a user mint some shares on a public vault.
    /// @param shares amount of shares minted.
    /// @param receiver address that will receive the LP token (shares).
    /// @param amount0 amount of token0 needed to mint shares.
    /// @param amount1 amount of token1 needed to mint shares.
    event LogMint(
        uint256 shares,
        address receiver,
        uint256 amount0,
        uint256 amount1
    );

    /// @notice event emitted when a user burn some of his shares.
    /// @param shares amount of share burned by the user.
    /// @param receiver address that will receive amounts of tokens
    /// related to burning the shares.
    /// @param amount0 amount of token0 that is collected from burning shares.
    /// @param amount1 amount of token1 that is collected from burning shares.
    event LogBurn(
        uint256 shares,
        address receiver,
        uint256 amount0,
        uint256 amount1
    );

    // #endregion events.

    /// @notice function used to mint share of the vault position
    /// @param shares_ amount representing the part of the position owned by receiver.
    /// @param receiver_ address where share token will be sent.
    /// @return amount0 amount of token0 deposited.
    /// @return amount1 amount of token1 deposited.
    function mint(
        uint256 shares_,
        address receiver_
    ) external payable returns (uint256 amount0, uint256 amount1);

    /// @notice function used to burn share of the vault position.
    /// @param shares_ amount of share that will be burn.
    /// @param receiver_ address where underlying tokens will be sent.
    /// @return amount0 amount of token0 withdrawn.
    /// @return amount1 amount of token1 withdrawn.
    function burn(
        uint256 shares_,
        address receiver_
    ) external returns (uint256 amount0, uint256 amount1);
}

